function Probe-Url($u) {
  try {
    $resp = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 25 -Headers @{ Accept = "*/*" }
    $body = $resp.Content
    $code = [int]$resp.StatusCode
  } catch {
    $ex = $_.Exception
    $resp = $_.Exception.Response
    if ($resp) {
      $code = [int]$resp.StatusCode
      $stream = $resp.GetResponseStream()
      $reader = New-Object System.IO.StreamReader($stream)
      $body = $reader.ReadToEnd()
    } else {
      $code = 0
      $body = $ex.Message
    }
  }
  $head = if ($body.Length -gt 200) { $body.Substring(0,200) } else { $body }
  $html = ($head -match '<!DOCTYPE html|<html') -and ($body.Substring(0, [Math]::Min(500, $body.Length)) -notmatch 'export ')
  $failed = $body -match 'Failed to resolve'
  $vim = $body -match 'ViMoneyInput|amountStringToNumber|numberToAmountString'
  $exp = $body -match 'export |export\{'
  [pscustomobject]@{ url=$u; http=$code; len=$body.Length; html_shell=$html; failed_resolve=$failed; has_vimoney=$vim; has_export=$exp; head=($head -replace "`r|`n"," ") }
}
